"""Editorial artifact transformation: v14 content only, no v15/v16 source."""
import runpy,pprint
from pathlib import Path
R=Path('/workspace/soil_global');O=R/'paper/v17_from_v14'; V=runpy.run_path(str(R/'paper/v14/main_text.py'))
TITLE='Joint organic–inorganic accounting separates projected soil stock decline from its timing'
ONE_SENTENCE='A depth-resolved inventory and conditional projections show why organic and inorganic soil carbon must be assessed together, without equating stock change with atmospheric CO₂ exchange.'
SHORT_TITLE='Soil stocks, spatial divergence and timing'
ABSTRACT="""Assessments of soil carbon rarely consider organic and inorganic stocks together or distinguish their projected equilibrium changes from their timing. Using 174,092 soil profiles, we estimate 2506 Pg soil organic carbon (SOC; 90% CI, 2263–2761) and 1598 Pg soil inorganic carbon (SIC; 1408–1801) in the upper 2 m. Under SSP5-8.5, space-for-time projections give an equilibrium SOC decrease of 378 Pg and SIC increase of 229 Pg, with a total stock decline of 150 Pg. With assumed first-order turnover, the projected total decline by 2100 is 180 Pg. Separate nitrogen-acidification experiments indicate SIC vulnerability but cannot establish a combined climate–nitrogen balance. Mineral-associated organic carbon carries a larger equilibrium loss than particulate carbon, but similar losses are projected by 2100 under the assumed turnover ranges. These are conditional soil-stock projections, not measurements of net atmospheric CO₂ exchange."""
STRUCTURED=[('INTRODUCTION','Organic and inorganic carbon occupy different depths and environments. Their joint soil-stock response, and the time over which it could emerge, cannot be inferred from either pool alone.'),('RATIONALE','We revisited a joint inventory and its existing climate, first-order turnover, nitrogen-acidification and organic-fraction outputs. Spatial associations are interpreted descriptively; separate experiments are not combined into a new scenario.'),('RESULTS','The upper 2 m stores 4105 Pg total carbon, including 2506 Pg SOC and 1598 Pg SIC; 89% of SIC is below 30 cm. The humidity–pH–SIC association is consistent with a proposed pathway, not proof of causation. Under SSP5-8.5, projected equilibrium changes are −378 Pg SOC and +229 Pg SIC, with ΔTC = −150 Pg; SOC decrease with SIC increase occurs on 50% of mapped land. Under the assumed turnover ranges, by-2100 changes are −188 Pg SOC, +7 Pg SIC and −180 Pg TC. Separate nitrogen experiments give topsoil SIC loss-only totals of 1.6–2.2 Pg over 2020–2050. For mineral topsoil fractions, equilibrium MAOC/POC decreases are 78/39 Pg, compared with 37/39 Pg by 2100. POC realizes most of its modeled committed decrease; the POC stock itself is not exhausted.'),('CONCLUSION','The central result is a conditional soil-stock decline whose magnitude and timing depend on which pools are included. It does not establish a net atmospheric CO₂ source or the sign of SIC change under joint climate and nitrogen forcing.')]
MAIN=[]
def h(t):MAIN.append(('h',t))
def p(t):MAIN.append(('p',t))
p("Soils contain both organic carbon (SOC) and inorganic carbon (SIC), but inventories and climate assessments predominantly track SOC [@batjes96;@sanderman17;@crowther16]. SIC includes pedogenic and inherited carbonates concentrated in drylands [@zamanian16;@monger15]. A recent digital soil-mapping synthesis estimated 2305 ± 636 Pg SIC in the upper 2 m and identified vulnerability to acidification [@huang24]. The question is therefore not simply how much carbon soils contain, but whether changes in the two stocks reinforce or oppose one another, where they do so, and on what assumed timescale.")
p("Spatial patterns suggest a possible divergence: organic stocks are associated with plant inputs, temperature and moisture, whereas carbonate occurrence is closely associated with pH and water balance [@koven17;@slessarev16]. Such cross-sectional relations do not establish a dynamic response. Moreover, carbonate formation and dissolution involve carbon sources, dissolved inorganic carbon (DIC) and lateral transport; a decline in SOC + SIC is not by itself a measured atmospheric CO₂ flux [@hamilton07;@west05]. We therefore distinguish the stock-accounting question from the atmospheric carbon-budget question.")
p("We use depth-resolved soil mapping to connect six questions: present partitioning, statistical associations, projected equilibrium geography, conditional timing, separate acidification vulnerability, and the organic fractions carrying the projected decline. We follow the observational screening and two-step SIC framework of Huang et al. [@huang24], adding organic-horizon handling, declustering, MAOC/POC fractions and assumed first-order turnover. No joint climate–nitrogen scenario is constructed. MAOC and POC are assessed within mineral soils and are not treated as an additional carbon stock on top of SOC.")
h('1. A deep inorganic stock complements the organic inventory')
p("Quality control retained 174,092 of 226,821 WoSIS profiles [@batjes20], with 107,482 topsoil SOC, 99,199 SIC and 118,807 pH records (table S1). Horizon values were harmonized to 0–30, 30–100 and 100–200 cm using mass-preserving splines [@bishop99;@malone09]. Gradient-boosted models [@chen16] represented pH, carbonate presence and amount, mineral SOC, organic-horizon probability and bulk density, with 0.5° declustering weights in the final workflow. Sampling is uneven: North America contributes 36% of topsoil SOC profiles and Asia 5%, and deep observations are much scarcer (fig. S22; table S18).")
p("Random 10-fold cross-validation gave carbonate-presence AUC values of 0.95–0.97, bulk-density R² of 0.77–0.81, mineral-topsoil-SOC R² of 0.64 and pH R² of 0.65–0.67; SIC amount was less well predicted (original-scale R², 0.31–0.49; table S3; fig. S1). These scores come from an unweighted search with three additional point-sampled SoilGrids covariates, whereas the final fold-models use the 32-covariate stack and declustering weights. They are therefore not a matched validation of every final workflow component. Random folds also estimate interpolation rather than spatial transfer skill [@ploton20;@meyer21].")
p("The upper 2 m stores 4105 Pg TC (90% CI, 3675–4549; ±265 Pg), comprising 2506 Pg SOC (2263–2761; ±151) and 1598 Pg SIC (1408–1801; ±119) (Table 1; Fig. 1; fig. S14). Thus SIC contributes 39% of TC. SOC layer stocks are 848, 818 and 841 Pg; SIC stocks are 178, 602 and 819 Pg (Fig. 1A). Consequently, 89% of SIC, compared with 66% of SOC, is below 30 cm. Independently rounded layers and totals are retained; they need not sum exactly. Regional depth summaries and latitude profiles are in figs. S17 and S16 and table S13.")
p("The spatial complement is equally important (Fig. 1, B–D). SIC exceeds 60% of TC on 26% of mapped land but contributes less than 5% on 40%. Arid Köppen–Geiger zones contain 1064 Pg SIC, while cold zones contain 1060 Pg SOC (fig. S15; table S14). Country rankings and national partitioning are supporting scale summaries, not separate steps in the argument (fig. S24; table S15). Comparisons with earlier inventories and independent LUCAS validation are retained in supplementary text S1 and table S6: depth-harmonized LUCAS bias remains +6.9 Mg C ha⁻¹ (R² ≈ 0.02). Hybrid 30″ maps do not justify finer-scale totals; their topsoil SIC integral differs substantially from the 10′ model, and deep 30″ SOC is provisional (fig. S12). This inventory establishes what must be counted; the next question is which spatial associations distinguish the pools.")
h('2. Spatial associations are consistent with a humidity–pH–SIC pathway')
p("TreeSHAP attribution separates the fitted models rather than proving environmental causation [@lundberg17;@lundberg20]. Climate contributes 66% of grouped mean |SHAP| for mineral SOC and 80% for pH, whereas soil variables contribute 74% for SIC presence and 55% for SIC amount (Fig. 2A; fig. S3). Predicted pH contributes 51% and 33% to SIC presence and amount, respectively. Dominant-driver maps and the full partial-dependence set are retained in SI rather than repeating the attribution in several main panels (figs. S5 and S25).")
p("The standardized path model describes 58,404 complete topsoil observations (Fig. 2B; fig. S8). The humidity-index–pH coefficient is −0.56 and the pH–SIC coefficient is +0.67; their product gives an indirect coefficient of −0.38. The direct humidity-index–SIC coefficient is +0.03 and the total is −0.35. The humidity-index–SOC coefficient is +0.35. These associations are consistent with the hypothesized water-balance–pH pathway [@slessarev16;@huang24], but arrows encode an assumed regression structure: unmeasured confounding, reverse relations and spatial covariation prevent a causal interpretation. These descriptive regressions use observed pH; the separate predictive SIC models use modeled pH.")
p("Observed carbonate occurrence has a fitted pH midpoint of 7.10 (n = 91,273), while the model partial-dependence breakpoint is 6.64 (Fig. 2, C and D; fig. S6). These are different summaries—an observational sigmoid and a model response curve—not interchangeable physiological thresholds. The weaker residual humidity dependence, SIC-amount curves and fraction-texture breakpoints remain in SI (figs. S4 and S5; table S11). Together these findings motivate a conditional projection test: if the present spatial associations were transferable, would future climate yield aligned or opposing stock changes?")
h('3. Equilibrium projections diverge spatially between SOC and SIC')
p("We applied the present-day models to 2081–2100 climates from six CMIP6 models under four SSPs [@oneill16], holding soil and terrain covariates fixed. The 10 final fold-models × six GCMs form a common ensemble; equilibrium maps and global means share this accounting (supplementary text S2). This space-for-time substitution supplies a target-state contrast, not a validated temporal trajectory. Under SSP5-8.5, equilibrium SOC decreases by 378 Pg (90% CI, 254–526) and SIC increases by 229 Pg (130–382), with TC decreasing by 150 Pg (41–245) (Table 2; Fig. 3, A and B). Under SSP1-2.6, ΔTC is −45 Pg with a CI from −110 to +4 Pg, so the equilibrium TC direction is unresolved there.")
p("Under SSP5-8.5, SOC decrease with SIC increase—the sign-defined trade-off—covers 69 Mkm², or 50% of mapped land. Co-loss covers 16%, joint gains 20%, and SOC gain with SIC decrease 13% (Fig. 3, C and D; table S8). These are classifications of ensemble-mean signs, not proof that every cell changes significantly. Strong SOC decreases occur in northern high latitudes, whereas SIC gains and decreases have a contrasting geography. Ensemble sign agreement, per-GCM spread and other SSP maps are in figs. S19 and S18. Country scatter and continental bars are retained with the original spatial panels (fig. S27), avoiding a second main figure for the same divergence.")
p("Köppen–Geiger transitions provide an additional spatial grouping rather than another mechanism: changed main classes occupy 19.1 Mkm² under SSP5-8.5, carrying SOC decrease of 61 Pg and SIC increase of 44 Pg (fig. S21; tables S8 and S17). Most projected redistribution occurs within unchanged main classes. The common message is spatial divergence, but its equilibrium magnitude does not tell a reader how much change could emerge by 2100. That timing question is treated separately.")
h('4. Assumed turnover changes the by-2100 stock balance')
p("We applied Δ(t) = Δ_eq[1 − exp(−t/τ)] with t = 85 years. SOC τ ranges are 20–100, 100–1000 and 500–3000 years by increasing depth; SIC τ is 1000–10,000 years for all layers, sampled log-uniformly [@carvalhais14;@he16;@shi20]. These literature-informed ranges are assumptions, not parameters fitted to repeated observations. Figure 4 therefore displays a conditional first-order calculation for SOC, SIC and TC only; it does not include MAOC/POC or nitrogen.")
p("Under these assumptions and SSP5-8.5, by-2100 SOC decreases by 188 Pg (90% CI, 105–292) and SIC increases by 7 Pg (2–19), giving TC decline of 180 Pg (100–282) (Fig. 4; Table 2; fig. S13). About half of the modeled equilibrium SOC decrease and 3% of the SIC increase are realized. The by-2100 TC decline is larger than the equilibrium decline because the positive SIC term is much more delayed. By-2100 TC means are −54, −97, −144 and −180 Pg across the four SSPs, with CIs excluding zero within this model. The inferred timing depends on τ and the validity of the target state; it is not observational confirmation of a lag or a measured net CO₂ emission. A separate disturbance can also reduce carbonate stocks, but it must be evaluated on its own experimental basis.")
h('5. A separate nitrogen experiment identifies acidification vulnerability')
p("We drove the empirical relation ΔpH = −0.06 N_in + 0.11 [@huang24;@guo10] with IMAGE fertilizer inputs for 2020–2050 [@stehfest14;@lange19], then reevaluated SIC with other covariates fixed. The relation was calibrated in Chinese croplands; GLOBIOM/INMS inputs were not obtained and SSP2-4.5 inputs were interpolated. Its positive intercept allows alkalinization at low cumulative input (Fig. 5A). We therefore distinguish loss-only totals (positive SIC changes excluded) from net totals (table S9).")
p("Topsoil loss-only SIC decreases are 1.6, 1.8, 2.1 and 2.2 Pg across the four SSPs, with corresponding upper-2-m losses of 13.4–17.4 Pg (Fig. 5B). Net decreases are 0.9–1.6 Pg in topsoil and 7.0–11.1 Pg in the upper 2 m. The topsoil maps locate agricultural exposure (Fig. 5, C and D); national rankings are supporting information (fig. S28). Applying the same topsoil ΔpH at every depth is an explicit assumption, not evidence for acidification propagation to 2 m within 30 years.")
p("These nitrogen experiments differ from the climate projections in forcing, time window, affected mask, depth assumptions and model configuration. Their magnitudes must not be subtracted to infer a combined SIC direction or a demonstrated reversal of climate-associated gains. No coupled response or robust combined direction is identified by this comparison. The smaller IMAGE estimates relative to the published 10–23 Pg topsoil losses [@huang24] are discussed with the fertilizer-input and transferability limitations in supplementary text S4; the high-N loss ratio is diagnostic, not a rerun scenario. The acidification result broadens the vulnerability assessment, while leaving open the joint response. The final question concerns the organic fractions underlying the projected SOC decline.")
h('6. Organic fractions separate shorter- and longer-term committed losses')
p("The mineral-soil fraction model uses 1005 harmonized MAOC/POC observations [@georgiou22;@georgiou_data] after excluding records without measured POC (fig. S2). Random-fold R² is 0.58 (five repeats, 0.57 ± 0.02; RMSE, 0.129; fig. S1). Texture associations support the distinction between particulate and mineral-associated pools [@lavallee20;@cotrufo19;@rasmussen18], but only 34 fraction records below 30 cm constrain subsoil estimates. In mineral topsoil, MAOC stores 518 Pg (90% CI, 473–565; ±28) and POC 183 Pg (163–205; ±13) (Fig. 6, A and B; Table 1). The 0–1 m MAOC estimate is 1048 Pg; comparisons with Georgiou et al. are retained as methodological context, not a main result (fig. S29).")
p("Under SSP5-8.5, projected equilibrium topsoil decreases are 78 Pg MAOC (90% CI, 38–124) and 39 Pg POC (22–60). With assumed τ ranges of 50–400 and 5–30 years, respectively, by-2100 decreases are 37 Pg MAOC (12–79) and 39 Pg POC (21–60) (Fig. 6, C and D; fig. S7; table S10). Thus POC realizes nearly all of its modeled committed decrease, not the disappearance of the POC stock. Both pools retain positive stocks. MAOC carries the larger delayed loss, although under SSP1-2.6 its change CI includes zero. These fraction projections exclude organic horizons and use a separate mineral-SOC/fraction workflow; they cannot be summed to validate the total-SOC projection. Fraction-level timing complements, but does not independently validate, the whole-stock accounting.")
h('Implications and limits of joint soil-stock accounting')
p("The closed argument is one of scope and timing: the inventory reveals a large deep inorganic stock; statistical associations motivate a conditional spatial projection; the equilibrium geography shows opposing pool changes; and assumed turnover makes the by-2100 total differ from the equilibrium contrast. Nitrogen adds a separate vulnerability, while MAOC/POC separates the organic component's committed changes. Equilibrium SIC increases should not be treated as an observed near-term offset, and soil-stock decline alone should not be entered as a net atmospheric CO₂ source [@canadell21]. Carbonate provenance, formation stoichiometry, DIC export and degassing require an explicit flux accounting that this analysis does not provide.")
p("Depth-explicit monitoring should retain both SOC and SIC rather than restricting attention to upper-30-cm organic carbon [@ipcc06;@ipcc19]. Fraction-resolved monitoring can distinguish a fast modeled response from a larger delayed commitment, but does not establish reversibility under management. Nitrogen and liming interventions also require regional buffering and downstream-carbon evidence [@zamanian18;@raza20;@hamilton07;@west05;@beerling20]. These are priorities for testing, not management effects estimated by this study.")
p("The necessary limits remain visible (supplementary text S6): space-for-time projections omit land-use change, vegetation/input feedbacks, irrigation, dust and soil-pCO₂ responses; τ is assumed; the search-CV and final workflows differ; random folds are spatially optimistic; SOC retains LUCAS bias; uncertainty excludes alternative model structures and depends on perturbation ranges; nitrogen forcing and transferability are uncertain; and subsoil fractions are sparse. The 10′ analysis cannot be presented as independent 1-km information. These limitations constrain both magnitude and interpretation, not merely confidence in a predetermined direction. Repeated observations, matched spatial validation and a coupled stock–DIC–gas accounting are needed before conditional stock contrasts can become causal or atmospheric-carbon conclusions.")
# Keep v14 methods but correct its CV claim and stock/atmosphere interpretation.
METHODS_SUMMARY=V['METHODS_SUMMARY'][:]
METHODS_SUMMARY[0]=METHODS_SUMMARY[0].replace('Hyperparameters were selected and accuracy assessed by random 10-fold cross-validation (tables S3 and S4);','Hyperparameters were selected by random 10-fold cross-validation of unweighted fits with three additional point-sampled SoilGrids covariates; final fold-models use the 32-covariate stack with declustering weights, so search-CV metrics are not a matched assessment of the final workflow (tables S3 and S4);')
METHODS_SUMMARY[0]+=' Path analysis and SHAP attribution are descriptive, not causal. Negative stock change is not equated with net CO₂ emission. Climate and nitrogen experiments are not summed. Rounded ensemble means are reported independently without forcing rounded arithmetic identities.'
ACK=V['ACK']
FIGFILES={1:'Fig1_inventory.png',2:'Fig2_associations.png',3:'Fig3_equilibrium_geography.png',4:'Fig4_kinetic_stock_change.png',5:'Fig5_nitrogen.png',6:'Fig6_organic_fractions.png'}
LEGENDS={
1:('Depth and spatial complementarity of present stocks.','(A) Global SOC and SIC by depth; bars, existing ensemble means; error bars, 90% CIs from fold-models × Monte Carlo. The total 0–200 cm TC stock is 4105 Pg C (3675–4549). (B) SIC as a share of TC in 0–200 cm. (C and D) SOC and SIC stocks, respectively, in 0–200 cm (Mg C ha⁻¹). Robinson maps on the 10′ grid; grey, not mapped. Color keys are outside map frames. Independently rounded layer and total means need not add exactly. Topsoil distributions, detailed maps and national summaries are retained in figs. S23 and S24.'),
2:('Descriptive associations relevant to the proposed humidity–pH–SIC pathway.','(A) Grouped TreeSHAP attribution for the existing topsoil models, 30,000 cells. (B) Selected humidity–pH–SIC regression subgraph (n = 58,404); the complete SOC-inclusive model is retained in fig. S8. Blue/red, positive/negative coefficients; line width scales with coefficient magnitude. The main diagram shows the pH-linked subgraph only and omits |β| < 0.05 paths; all coefficients, including the SOC paths, are in table S11. The humidity–pH–SIC coefficient product is −0.38. Arrows encode model assumptions, not established causal links. (C) Stored binned observations (points) and the previously fitted carbonate-occurrence sigmoid (n = 91,273; pH₅₀ = 7.10; k = 3.41), redrawn from its stored coefficients; the complete observed relation is also retained in fig. S6. (D) Model partial dependence on predicted pH, with breakpoint 6.64. The sigmoid midpoint and PDP breakpoint summarize different quantities. Remaining PDPs and dominant-driver maps are supporting information.'),
3:('Projected equilibrium geography and co-occurring signs.','(A and B) Equilibrium ΔSOC and ΔSIC (0–200 cm; Mg C ha⁻¹) under SSP5-8.5. (C) Joint sign classes of the same ensemble-mean fields. (D) Area shares and color key outside the map: SOC−/SIC+ (trade-off), 50%; SOC−/SIC− (co-loss), 16%; SOC+/SIC+, 20%; SOC+/SIC−, 13%. Denominator, 137.3 Mkm²; zero change is classified with the non-positive class as in the original sign convention. These are signs of mean changes, not cellwise significance tests. Ensemble, 10 final fold-models × six GCMs; future climate, 2081–2100 relative to the 1970–2000 baseline, with soil and terrain fixed. Map integrals agree with unrounded ensemble means. Country/continental summaries and scenario details remain in figs. S26 and S27.'),
4:('Conditional timing of SOC, SIC and total-stock change.','(A to C) SOC, SIC and TC changes, respectively (0–200 cm; Pg C), at the projected equilibrium target (dark) and by 2100 under assumed first-order response (light). Bars, ensemble means; error bars, 90% CIs. By-2100 results sample log-uniform τ: SOC 20–100, 100–1000 and 500–3000 years by depth; SIC 1000–10,000 years, with t = 85 years. SSP5-8.5 equilibrium ΔTC is −150 Pg (−245 to −41), versus −180 Pg (−282 to −100) by 2100. Timing is assumption-dependent and not validated by temporal observations. No nitrogen or organic-fraction result is included here.'),
5:('Nitrogen-driven acidification as a separate experiment.','(A) Cropland ΔpH distributions for 2020–2050 using ΔpH = −0.06 N_in + 0.11 and IMAGE inputs. Positive values reflect the fitted intercept. (B) Loss-only SIC decreases in 0–30 and 0–200 cm, with 90% CIs across 10 fold-models; †SSP2-4.5 fertilizer inputs interpolated. The deeper estimate assumes the topsoil pH change applies at every depth. (C and D) Topsoil ΔSIC under SSP1-2.6 and SSP5-8.5 (Mg C ha⁻¹). Grey, not mapped. National ranks are retained in fig. S28; net totals in table S9. Climate and nitrogen experiments have different horizons, masks and assumptions and are not combined to infer a joint direction.'),
6:('Conditional short- and longer-term changes within mineral-soil SOC.','(A) MAOC fraction (%) and (B) MAOC stock (Mg C ha⁻¹) in 0–30 cm. Baseline stocks are 518 Pg MAOC (90% CI, 473–565) and 183 Pg POC (163–205). (C and D) MAOC and POC changes, respectively, at equilibrium (dark) and by 2100 (light); error bars, 90% CIs, including τ sampling for the time-limited response. τ ranges, MAOC 50–400 and POC 5–30 years, with t = 85 years. SSP5-8.5 decreases are 78/39 Pg at equilibrium and 37/39 Pg by 2100. The realized fraction describes the committed loss, not exhaustion of either positive remaining stock. Organic horizons are excluded; this workflow is not directly additive with the total-SOC projections. Method comparison and stock bivariate details are in fig. S29.')}
for name in ['TITLE','SHORT_TITLE','ONE_SENTENCE','STRUCTURED','ABSTRACT','MAIN','METHODS_SUMMARY','ACK','LEGENDS','FIGFILES']:
 with open(O/'main_text.py','a' if name!='TITLE' else 'w') as f:f.write(name+' = '+pprint.pformat(globals()[name],width=120,sort_dicts=False)+'\n\n')
